class BtsStatus(object):
    """
    The class corresponding to BTS status page on selenium_coam web, all operations under BTS status
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver):
        self._bts_start_up_view = BtsStartUpViewPage(driver)
        self._site_view = SiteViewPage(driver)
        self._detailed_site_view = DetailedSiteViewPage(driver)
        self._cells = CellsPage(driver)
        self._carrier_aggregation = CarrierAggregationPage(driver)
        self._data_streams_by_cell = DataStreamsByCellPage(driver)
        self._data_streams_by_carrier = DataStreamsByCarrierPage(driver)
        self._site_report = SiteReportPage(driver)

    @property
    def bts_start_up_view(self):
        return self._bts_start_up_view

    @property
    def site_view(self):
        return self._site_view

    @property
    def detailed_site_view(self):
        return self._detailed_site_view

    @property
    def cells(self):
        return self._cells

    @property
    def carrier_aggregation(self):
        return self._carrier_aggregation

    @property
    def data_streams_by_cell(self):
        return self._data_streams_by_cell

    @property
    def data_streams_by_carrier(self):
        return self._data_streams_by_carrier

    @property
    def site_report(self):
        return self._site_report


class BtsStartUpViewPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['BTS Status', 'BTS Start-up View']

    def __init__(self, driver):
        super(BtsStartUpViewPage, self).__init__(driver)
        self._driver = driver

    def get_bts_start_up_view_info(self, timeout):
        bts_start_up_modal = BtsStartUpViewModal(self._driver)
        bts_start_up_modal.wait_for_start_up_view_modal_appear(timeout)
        info = bts_start_up_modal.get_bts_start_up_view_info()
        bts_start_up_modal.close(timeout)
        return info

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class SiteViewPage(NavigatablePage):
    """
    As a class will be called by BtsStatus, all operations on Site View will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['BTS Status', 'Site Runtime View', 'Site View']

    def __init__(self, driver):
        super(SiteViewPage, self).__init__(driver)
        self._navigation_panel = SiteViewPageNavigationPanel(driver)
        self._view_panel = SiteViewPageViewPanel(driver)
        self._detail_panel = SiteViewPageDetailPanel(driver)

    def get_bts_name(self, timeout=60):
        """
        Method for getting bts name on Site View page
        """
        return self._detail_panel.get_bts_name(timeout)

    def lock_bts(self, timeout=60):
        """
        Method for locking bts on Site View page
        """
        return self._view_panel.lock_bts(timeout)

    def unlock_bts(self, timeout=60):
        """
        Method for unlocking bts on Site View page
        """
        return self._view_panel.unlock_bts(timeout)

    def get_bts_lock_or_unlock(self, timeout=60):
        """
        Method for getting current BTS status
        :param timeout: int, timeout
        :return: str, "Lock BTS" or "Unlock BTS"
        """
        return self._view_panel.get_bts_lock_or_unlock(timeout)

    def get_led_status_of_an_unit(self, unit):
        return self._view_panel.get_led_status_of_an_unit(unit)

    def lock_abil(self, abil_id, timeout):
        """
        Method for locking abil on Site View page
        """
        self._view_panel.lock_abil(abil_id, timeout)

    def unlock_abil(self, abil_id, timeout):
        """
        Method for unlocking abil on Site View page
        """
        self._view_panel.unlock_abil(abil_id, timeout)

    def lock_baseband(self, baseband_idx, timeout):
        """
        Method for locking baseband on Site View page
        """
        self._view_panel.lock_baseband(baseband_idx, timeout)

    def unlock_baseband(self, baseband_idx, timeout):
        """
        Method for unlocking baseband on Site View page
        """
        self._view_panel.unlock_baseband(baseband_idx, timeout)

    def get_cell_group_status(self, cell_group_id, timeout):
        """
        Method for get cell group status under Details panel on Site View page
        """
        return self._view_panel.get_cell_group_status(cell_group_id, timeout)

    def lock_cell_group(self, cell_group_id, timeout):
        """
        Method for locking cell_group on Site View page
        """
        self._view_panel.lock_cell_group(cell_group_id, timeout)

    def unlock_cell_group(self, cell_group_id, timeout):
        """
        Method for unlocking cell_group on Site View page
        """
        self._view_panel.unlock_cell_group(cell_group_id, timeout)

    def get_amf_info(self):
        """
        Method for getting ng link status after clicking AMF 1
        :return: dict, specific information of AMF 1
        """
        self._view_panel.select_amf_field()
        return self._detail_panel.get_detail_info_table()

    def reset_hardware(self, hw_name, timeout):
        """
        Method for resetting given hardware from GUI by clicking reset button on detail panel.
        :param hw_name: str, name of hardawre
        :param timeout: int, timeout to raise TimeoutException
        """
        self._view_panel.show_hardware_detail_panel(hw_name)
        self._detail_panel.reset_hardware(timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class SiteViewPageNavigationPanel(NavigationPanel):
    pass


class SiteViewPageViewPanel(ViewPanel):
    _BTS_LOCK_UNLOCK_BUTTON_XPATH = "//site-lock-unlock//ui-button"
    _BTS_LOCK_FIELD = 'Lock BTS'
    _BTS_UNLOCK_FIELD = 'Unlock BTS'
    _ABILS_XPATH = "(//div[contains(text( ), 'ABIL') or contains(text( ), 'ABIO')])"
    _ABILS_TITLE_XPATH = '/following-sibling::div'
    _CELL_GROUP_XPATH = "(//div[@class='cell-group-content']/div)"
    _CELL_GROUP_TITLE_XPATH = "//div[@class='block-headers']/div"
    _AMF1_FIELD_XPATH = "//div[@class='block-headers']/div[text()='AMF 1']"
    _BASE_HW_XPATH = "//div[contains(text(), '{}')]"

    def __init__(self, driver):
        super(SiteViewPageViewPanel, self).__init__(driver)
        self._detail_panel = SiteViewPageDetailPanel(driver)

    def _change_bts_status(self, filed, timeout):
        self.wait_for_enable((By.XPATH, self._BTS_LOCK_UNLOCK_BUTTON_XPATH), timeout)
        try:
            current_status = self.get_attribute_by_xpath(self._BTS_LOCK_UNLOCK_BUTTON_XPATH, "a-title")
        except NoSuchAttributeException:
            current_status = self.get_attribute_by_xpath(self._BTS_LOCK_UNLOCK_BUTTON_XPATH, "a-text")
        if filed != current_status:
            raise InvalidElementStateException('bts is already {}'.format(filed.lower().split(' ')[0]))
        self.click_enabled_element((By.XPATH, self._BTS_LOCK_UNLOCK_BUTTON_XPATH))

        lock_or_unlock = LockOrUnlockBTSModal(self.driver)
        lock_or_unlock.wait_until_lock_or_unlock_modal_apper(timeout)
        lock_or_unlock.confirm(timeout)

        self.wait_for_text_not_present_in_element((By.XPATH, self._BTS_LOCK_UNLOCK_BUTTON_XPATH),
                                                  current_status,
                                                  timeout)
        return self.get_attribute_by_xpath(self._BTS_LOCK_UNLOCK_BUTTON_XPATH, "a-title")

    def lock_bts(self, timeout):
        """
        Method for locking bts on Site View page
        """
        return self._change_bts_status(self._BTS_LOCK_FIELD, timeout)

    def unlock_bts(self, timeout):
        """
        Method for unlocking bts on Site View page
        """
        return self._change_bts_status(self._BTS_UNLOCK_FIELD, timeout)

    def get_bts_lock_or_unlock(self, timeout):
        """
        Method for getting current BTS status
        :param timeout: int, timeout
        :return: str, "Lock BTS" or "Unlock BTS"
        """
        return self.get_attribute_by_xpath(self._BTS_LOCK_UNLOCK_BUTTON_XPATH, "a-title", timeout)

    def get_led_status_of_an_unit(self, unit):
        led_xpath = ('//div[contains(text(), "{}")]/../..//div[@class="block-icons"]'
                     '/div[contains(@class, "site-widget-diode")]').format(unit)
        return self.get_attribute_by_xpath(led_xpath, "title")

    def lock_abil(self, abil_id, timeout):
        abil_xpath = self._get_baseband_xpath_and_info_by_id(abil_id)
        self.show_detail_panel(abil_xpath)
        self._detail_panel.lock_abil(timeout)

    def unlock_abil(self, abil_id, timeout):
        abil_xpath = self._get_baseband_xpath_and_info_by_id(abil_id)
        self.show_detail_panel(abil_xpath)
        self._detail_panel.unlock_abil(timeout)

    def lock_baseband(self, baseband_idx, timeout):
        baseband_xpath = self._get_baseband_xpath_and_info_by_id(baseband_idx)
        self.show_detail_panel(baseband_xpath)
        self._detail_panel.lock_baseband(timeout)

    def unlock_baseband(self, baseband_idx, timeout):
        baseband_xpath = self._get_baseband_xpath_and_info_by_id(baseband_idx)
        self.show_detail_panel(baseband_xpath)
        self._detail_panel.unlock_baseband(timeout)

    def _get_baseband_xpath_and_info_by_id(self, abil_id):
        abil_xpath_list = self.get_elements_xpath_list(self._ABILS_XPATH)
        for abil_xpath in abil_xpath_list:
            abil_title_xpath = abil_xpath + self._ABILS_TITLE_XPATH
            if abil_id == int(self.get_text_by_xpath(abil_title_xpath, timeout=60)[-1]):
                return abil_xpath

    def get_cell_group_status(self, cell_group_id, timeout):
        cell_group_xpath = self._get_cell_group_xpath_and_info_by_id(cell_group_id)
        self.show_detail_panel(cell_group_xpath)
        return self._detail_panel._get_cur_cell_group_status(timeout)

    def lock_cell_group(self, cell_group_id, timeout):
        cell_group_xpath = self._get_cell_group_xpath_and_info_by_id(cell_group_id)
        self.show_detail_panel(cell_group_xpath)
        self._detail_panel.lock_cell_group(timeout)

    def unlock_cell_group(self, cell_group_id, timeout):
        cell_group_xpath = self._get_cell_group_xpath_and_info_by_id(cell_group_id)
        self.show_detail_panel(cell_group_xpath)
        self._detail_panel.unlock_cell_group(timeout)

    def _get_cell_group_xpath_and_info_by_id(self, cell_group_id):
        cell_group_xpath_list = self.get_elements_xpath_list(self._CELL_GROUP_XPATH)
        for cell_group_xpath in cell_group_xpath_list:
            cell_group_title_xpath = cell_group_xpath + self._CELL_GROUP_TITLE_XPATH
            if cell_group_id == int(self.get_text_by_xpath(cell_group_title_xpath, timeout=60)[-1]):
                return cell_group_xpath

    def select_amf_field(self):
        self.show_detail_panel(self._AMF1_FIELD_XPATH)

    def show_hardware_detail_panel(self, hw_name, hw_xpath=_BASE_HW_XPATH):
        self.show_detail_panel(hw_xpath.format(hw_name))


class SiteViewPageDetailPanel(DetailPanel):
    _LOCK_OR_UNLOCK_BUTTON_XPATH = ('//div[@dist-name="operationDistName"]'
                                    '//ui-button[@a-text="Lock" or @a-text="Unlock" ]')
    _CELL_GROUP_LOCK_OR_UNLOCK_BUTTON_XPATH = '//div[@dist-name="operationDistName"]//ui-button'
    _CELL_GROUP_LOCK_BUTTON_XPATH = '//div[@dist-name="operationDistName"]//ui-button[contains(@a-text, "Lock")]'
    _CELL_GROUP_UNLOCK_BUTTON_XPATH = '//div[@dist-name="operationDistName"]//ui-button[contains(@a-text, "Unlock")]'
    _LOCK_STATUS = "Lock"
    _UNLOCK_STATUS = "Unlock"
    _BTS_NAME_XPATH = '//td[text()="BTS name:"]/following-sibling::td'
    _RESET_BUTTON_XPATH = "//ui-button[@a-text='Reset']/button"
    _OPERATION_NOT_AVAILABLE = 'Operation not available'

    def __init__(self, driver):
        super(SiteViewPageDetailPanel, self).__init__(driver)

    def _change_baseband_status_on_modal(self, state, timeout):
        baseband_modal = BaseBandModuleLockModal(self.driver)
        baseband_modal.wait_until_lock_abil_modal_appear(timeout)
        if state == self._LOCK_STATUS:
            baseband_modal.lock(timeout)
        elif state == self._UNLOCK_STATUS:
            baseband_modal.unlock(timeout)

    def lock_abil(self, timeout):
        if self._UNLOCK_STATUS == self.get_text_by_xpath(self._LOCK_OR_UNLOCK_BUTTON_XPATH, timeout):
            raise UnexpectedElementState("Current status of abil is lock, no need to lock")

        self.click_enabled_element_after_visible((By.XPATH, self._LOCK_OR_UNLOCK_BUTTON_XPATH), timeout)
        self._change_baseband_status_on_modal(self._LOCK_STATUS, timeout)

    def unlock_abil(self, timeout):
        if self._LOCK_STATUS == self.get_text_by_xpath(self._LOCK_OR_UNLOCK_BUTTON_XPATH, timeout):
            raise UnexpectedElementState("Current status of abil is unlock, no need to unlock")

        self.click_enabled_element_after_visible((By.XPATH, self._LOCK_OR_UNLOCK_BUTTON_XPATH), timeout)
        self._change_baseband_status_on_modal(self._UNLOCK_STATUS, timeout)

    def lock_baseband(self, timeout):
        if self._UNLOCK_STATUS == self.get_text_by_xpath(self._LOCK_OR_UNLOCK_BUTTON_XPATH, timeout):
            raise UnexpectedElementState("Current status of baseband is lock, no need to lock")

        self.click_enabled_element_after_visible((By.XPATH, self._LOCK_OR_UNLOCK_BUTTON_XPATH), timeout)
        self._change_baseband_status_on_modal(self._LOCK_STATUS, timeout)

    def unlock_baseband(self, timeout):
        if self._LOCK_STATUS == self.get_text_by_xpath(self._LOCK_OR_UNLOCK_BUTTON_XPATH, timeout):
            raise UnexpectedElementState("Current status of baseband is unlock, no need to unlock")

        self.click_enabled_element_after_visible((By.XPATH, self._LOCK_OR_UNLOCK_BUTTON_XPATH), timeout)
        self._change_baseband_status_on_modal(self._UNLOCK_STATUS, timeout)

    def _get_cur_cell_group_status(self, timeout):
        self.wait_for_visibility_by_xpath(self._CELL_GROUP_LOCK_OR_UNLOCK_BUTTON_XPATH, timeout)
        for elem in self.driver.find_elements_by_xpath(self._CELL_GROUP_LOCK_OR_UNLOCK_BUTTON_XPATH):
            a_text = elem.get_attribute('a-text')
            a_title = elem.get_attribute('a-title')
            if a_title == self._OPERATION_NOT_AVAILABLE:
                return a_text

    def _change_cell_group_status_on_modal(self, state, timeout):
        cell_group_modal = LockCellGroupModal(self.driver)
        cell_group_modal.wait_until_lock_cell_group_modal_appear(timeout)
        if state == self._LOCK_STATUS:
            cell_group_modal.lock(timeout)
        elif state == self._UNLOCK_STATUS:
            cell_group_modal.unlock(timeout)

    def lock_cell_group(self, timeout):
        if self._LOCK_STATUS == self._get_cur_cell_group_status(timeout):
            raise UnexpectedElementState("Current status of cell group is locked, no need to lock")
        self.click_enabled_element_after_visible((By.XPATH, self._CELL_GROUP_LOCK_BUTTON_XPATH), timeout)
        self._change_cell_group_status_on_modal(self._LOCK_STATUS, timeout)

    def unlock_cell_group(self, timeout):
        if self._UNLOCK_STATUS == self._get_cur_cell_group_status(timeout):
            raise UnexpectedElementState("Current status of cell group is unlocked, no need to unlock")
        self.click_enabled_element_after_visible((By.XPATH, self._CELL_GROUP_UNLOCK_BUTTON_XPATH), timeout)
        self._change_cell_group_status_on_modal(self._UNLOCK_STATUS, timeout)

    def get_bts_name(self, timeout):
        return self.get_text_by_xpath(self._BTS_NAME_XPATH, timeout)

    def reset_hardware(self, timeout):
        self.wait_until_element_is_clickable(self._RESET_BUTTON_XPATH, timeout=timeout)
        ResetModalCommonOperation(self.driver).click_reset_and_confirm(self._RESET_BUTTON_XPATH)


class DetailedSiteViewPage(NavigatablePage):
    """
    As a class will be called by BtsStatus, all operations on Detailed Site View will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['BTS Status', 'Site Runtime View', 'Detailed Site View']
    RETU_BASE_XPATH = '//div[@aria-label="Remote Electrical Tilt Unit 1"]//div[text()="{}"]'
    RAEU_BASE_XPATH = '//div[@aria-label="Remote Antenna Extension Unit 1"]//div[text()="{}"]'
    PHYSICAL_POAT_XPATH = '//div[contains(@aria-label, "{}")]'
    BASE_HW_XPATH_UNDER_VIEW_PANEL = ("//div[contains(@class,'view-content-wrapper')]"
                                      "//div/descendant-or-self::*[text()='{}']")
    SFP_XPATH = '//div[div[contains(text(), "{}")]]/parent::div//span[text()="{}"]'
    SFP_LOCK_BUTTON_XPATH = '//lane-info-section//tr[td[contains(text(), "{}")]]//button'

    def __init__(self, driver):
        super(DetailedSiteViewPage, self).__init__(driver)
        self._navigation_panel = DetailedSiteViewPageNavigationPanel(driver)
        self._view_panel = DetailedSiteViewPageViewPanel(driver)
        self._detail_panel = DetailedSiteViewPageDetailPanel(driver)

    def get_physical_ports_info(self, physical_port):
        self._view_panel.show_hardware_detail_panel(physical_port, self.PHYSICAL_POAT_XPATH)
        return self._detail_panel.get_detail_info_table()

    def get_hw_info(self, hw_name, fuzzy_match=True):
        if fuzzy_match:
            self._view_panel.show_hardware_detail_panel(hw_name)
        else:
            self._view_panel.show_hardware_detail_panel(hw_name, self.BASE_HW_XPATH_UNDER_VIEW_PANEL)
        return self._detail_panel.get_detail_info_table()

    def get_hw_parameters(self, hw_name):
        self._view_panel.show_hardware_detail_panel(hw_name)
        return self._detail_panel.get_parameters_info()

    def reset_hardware(self, hw_name, timeout):
        self._view_panel.show_hardware_detail_panel(hw_name)
        self._detail_panel.reset_hardware(timeout)

    def lock_ru(self, hw_name, timeout=120):
        self._view_panel.show_hardware_detail_panel(hw_name)
        return self._detail_panel.lock_hardware('RU', timeout)

    def unlock_ru(self, hw_name, timeout=120):
        self._view_panel.show_hardware_detail_panel(hw_name)
        return self._detail_panel.unlock_hardware('RU', timeout)

    def reset_site(self):
        self._view_panel.reset_site()

    def reset_ald(self, reset_type, hw_name):
        """
        Method for resetting ALD under Detailed Site View of BTS status page
        :param reset_type: str, "software" or "hardware" can be passed in
        :param hw_name: str, ALD name, such as "ALD-1"
        """
        self._view_panel.show_hardware_detail_panel(hw_name)
        self._detail_panel.reset_ald(reset_type)

    def get_tls_status(self, tls_name):
        self._view_panel.show_tls_detail_panel(tls_name)
        return self._detail_panel.get_detail_info_table()

    def get_raeu_info(self, raeu_index):
        hw_name = 'RAEU-{}'.format(raeu_index)
        self._view_panel.show_hardware_detail_panel(hw_name, self.RAEU_BASE_XPATH)
        return self._detail_panel.get_detail_info_table()

    def get_retu_info(self, retu_index, is_retu=True):
        """
        Method for getting specific information of RETU under Detailed Site View of BTS status page
        :param retu_index: int, index of RETU or is_RETU:
        :param is_retu: bool, RETU will be choosen if is_retu is True, or RETU_R will be choosen
        :return: dict, specific information of RETU or RETU_R
        """
        if is_retu:
            hw_name = "RETU-{}".format(retu_index)
        else:
            hw_name = "RETU_R-{}".format(retu_index)
        self._view_panel.show_hardware_detail_panel(hw_name, self.RETU_BASE_XPATH)
        return self._detail_panel.get_detail_info_table()

    def calibrate_retu(self, hw_name):
        """
        Method for calibrating retu under Detailed Site View of BTS status page
        :param hw_name: str, RETU name, such as "RETU-1"
        """
        self._view_panel.show_hardware_detail_panel(hw_name, self.RETU_BASE_XPATH)
        self._detail_panel.calibrate_retu()

    def set_retu_angles(self, hw_name, **configuration):
        """
        Method for setting RETU angles under Detailed Site View of BTS status page
        :param hw_name: str, RETU name, such as "RETU-1"
        :param configuration: dict, angles configurations
        {
            "angle": 1, (optional)
            "mechanicalTiltAngle": 0, (optional)
            "minTiltAngle": 0, (optional)
            "maxTiltAngle": 0 (optional)
        }
        """
        self._view_panel.show_hardware_detail_panel(hw_name, self.RETU_BASE_XPATH)
        self._detail_panel.set_retu_angles(**configuration)

    def lock_lane_from_sfp(self, hw_name, object_name, lane_id):
        self._view_panel.show_detail_panel(self.SFP_XPATH.format(hw_name, object_name))
        return self._detail_panel.lock_hardware(lane_id,
                                                lock_unlock_button_xpath=self.SFP_LOCK_BUTTON_XPATH.format(lane_id))

    def unlock_lane_from_sfp(self, hw_name, object_name, lane_id):
        self._view_panel.show_detail_panel(self.SFP_XPATH.format(hw_name, object_name))
        return self._detail_panel.unlock_hardware(lane_id,
                                                  lock_unlock_button_xpath=self.SFP_LOCK_BUTTON_XPATH.format(lane_id))

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class DetailedSiteViewPageNavigationPanel(NavigationPanel):
    pass


class DetailedSiteViewPageViewPanel(ViewPanel):
    _RESET_SITE_BUTTON_XPATH = "//ui-button[@a-text='Reset Site']/button"
    _BASE_HW_XPATH = "//div[contains(text(), '{}')]"
    _BASE_EXT_XPATH = "//div[@class='runtime-view-container']//*[contains(text(), '{}')]"

    def __init__(self, driver):
        super(DetailedSiteViewPageViewPanel, self).__init__(driver)

    def reset_site(self):
        ResetModalCommonOperation(self.driver).click_reset_and_confirm(self._RESET_SITE_BUTTON_XPATH)

    def show_hardware_detail_panel(self, hw_name, hw_xpath=_BASE_HW_XPATH):
        self.show_detail_panel(hw_xpath.format(hw_name))

    def show_tls_detail_panel(self, tls_name):
        self.show_detail_panel(self._BASE_EXT_XPATH.format(tls_name))


class DetailedSiteViewPageDetailPanel(DetailPanel):
    _RESET_BUTTON_XPATH = "//ui-button[@a-text='Reset']/button"
    _LOCK_OR_UNLOCK_BUTTON_XPATH = '//ui-button[@a-text="Lock" or @a-text="Unlock"]/button'
    _CALIBRATE_BUTTON_XPATH = "//ui-button[@a-text='Calibrate']/button"
    _SET_ANGLES_BUTTON_XPATH = "//ui-button[@a-text='Set Angles']/button"
    LOCK_STATUS = "Lock"
    UNLOCK_STATUS = "Unlock"

    def __init__(self, driver):
        super(DetailedSiteViewPageDetailPanel, self).__init__(driver)

    def lock_hardware(self, hw_name, timeout=120, lock_unlock_button_xpath=None):
        if not lock_unlock_button_xpath:
            lock_unlock_button_xpath = self._LOCK_OR_UNLOCK_BUTTON_XPATH

        current_status = self.get_text_by_xpath(lock_unlock_button_xpath)
        if self.LOCK_STATUS != current_status:
            logging.warning("{} is locked now, no need to lock again".format(hw_name))
            return self.LOCK_STATUS

        LockModalCommonOperation(self.driver).click_lock_and_confirm(lock_unlock_button_xpath)
        self.wait_for_text_present_in_element((By.XPATH, lock_unlock_button_xpath),
                                              self.UNLOCK_STATUS, timeout)
        return self.LOCK_STATUS

    def unlock_hardware(self, hw_name, timeout=120, lock_unlock_button_xpath=None):
        if not lock_unlock_button_xpath:
            lock_unlock_button_xpath = self._LOCK_OR_UNLOCK_BUTTON_XPATH

        current_status = self.get_text_by_xpath(lock_unlock_button_xpath)
        if self.UNLOCK_STATUS != current_status:
            logging.warning("{} is unlocked now, no need to unlock again".format(hw_name))
            return self.UNLOCK_STATUS

        UnlockModalCommonOperation(self.driver).click_unlock_and_confirm(lock_unlock_button_xpath)
        self.wait_for_text_present_in_element((By.XPATH, lock_unlock_button_xpath),
                                              self.LOCK_STATUS,
                                              timeout)
        return self.UNLOCK_STATUS

    def reset_hardware(self, timeout):
        self.wait_until_element_is_clickable(self._RESET_BUTTON_XPATH, timeout=timeout)
        ResetModalCommonOperation(self.driver).click_reset_and_confirm(self._RESET_BUTTON_XPATH)

    def reset_ald(self, reset_type):
        self.click_enabled_element((By.XPATH, self._RESET_BUTTON_XPATH))
        AldResetModal(self.driver).wait_until_reset_modal_appear()
        AldResetModal(self.driver).reset_ald(reset_type)

    def calibrate_retu(self):
        self.click_enabled_element((By.XPATH, self._CALIBRATE_BUTTON_XPATH))
        CalibrateRetuModal(self.driver).wait_until_calibrate_modal_appear()
        CalibrateRetuModal(self.driver).calibrate()

    def set_retu_angles(self, **configuration):
        self.click_enabled_element((By.XPATH, self._SET_ANGLES_BUTTON_XPATH))
        SetAngleModal(self.driver).wait_until_set_angle_modal_appear()
        SetAngleModal(self.driver).configure_angles(**configuration)
        SetAngleModal(self.driver).save()


class CellsPage(NavigatablePage):
    """
    As a class will be called by BtsStatus, all operations on Cells will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['BTS Status', 'Site Runtime View', 'Cells']
    _GLOBAL_CELL_ID = 'Global cell ID'

    def __init__(self, driver):
        super(CellsPage, self).__init__(driver)
        self._navigation_panel = CellsPageNavigationPanel(driver)
        self._view_panel = CellsPageViewPanel(driver)
        self._detail_panel = CellsPageDetailPanel(driver)

    def get_cell_info(self, cell_id):
        _, cell_info = self._get_cell_xpath_and_info_by_id(cell_id)
        return cell_info

    def lock_cell(self, cell_id, timeout=60):
        cell_xpath, _ = self._get_cell_xpath_and_info_by_id(cell_id)
        self._view_panel.show_detail_panel(cell_xpath)
        self._detail_panel.lock_cell(timeout)

    def unlock_cell(self, cell_id, timeout=60):
        cell_xpath, _ = self._get_cell_xpath_and_info_by_id(cell_id)
        self._view_panel.show_detail_panel(cell_xpath)
        self._detail_panel.unlock_cell(timeout)

    def _get_cell_xpath_and_info_by_id(self, cell_id):
        cell_xpath_list = self._view_panel.get_cell_xpath_list(timeout=60)
        for cell_xpath in cell_xpath_list:
            cell_info = self._get_cell_info_by_xpath(cell_xpath)
            if cell_id == int(cell_info[self._GLOBAL_CELL_ID]):
                return cell_xpath, cell_info

    def _get_cell_info_by_xpath(self, cell_xpath):
        self._view_panel.show_detail_panel(cell_xpath)
        return self._detail_panel.get_detail_info_table()

    def get_number_of_cells(self, timeout=60):
        return len(self._view_panel.get_cell_xpath_list(timeout))

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class CellsPageNavigationPanel(NavigationPanel):
    pass


class CellsPageViewPanel(ViewPanel):
    _CELLS_XPATH = "(//div[@model='cell'])"

    def __init__(self, driver):
        super(CellsPageViewPanel, self).__init__(driver)

    def get_cell_xpath_list(self, timeout):
        return self.get_elements_xpath_list(self._CELLS_XPATH, timeout)


class CellsPageDetailPanel(DetailPanel):
    _LOCK_OR_UNLOCK_BUTTON_XPATH = '//div[@dist-name="operationDistName"]//ui-button'
    _LOCK_STATUS = "Lock"
    _UNLOCK_STATUS = "Unlock"
    _AVAILABILITY_STATE_XATH = '//td[contains(text(), "Administrative state")]//following-sibling::td'

    def __init__(self, driver):
        super(CellsPageDetailPanel, self).__init__(driver)

    def _change_cell_status_on_modal(self, state, timeout):
        cell_modal = LockCellModal(self.driver)
        cell_modal.wait_until_lock_cell_modal_appear(timeout)
        if state == self._LOCK_STATUS:
            cell_modal.lock(timeout)
        elif state == self._UNLOCK_STATUS:
            cell_modal.unlock(timeout)

    def lock_cell(self, timeout):
        if self._UNLOCK_STATUS == self.get_text_by_xpath(self._LOCK_OR_UNLOCK_BUTTON_XPATH, timeout):
            raise UnexpectedElementState("Current status of cell is locked, no need to lock")

        self.click_enabled_element_after_visible((By.XPATH, self._LOCK_OR_UNLOCK_BUTTON_XPATH), timeout)
        self._change_cell_status_on_modal(self._LOCK_STATUS, timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._AVAILABILITY_STATE_XATH), 'Locked', timeout)

    def unlock_cell(self, timeout):
        if self._LOCK_STATUS == self.get_text_by_xpath(self._LOCK_OR_UNLOCK_BUTTON_XPATH, timeout):
            raise UnexpectedElementState("Current status of cell is unlock, no need to unlock")

        self.click_enabled_element_after_visible((By.XPATH, self._LOCK_OR_UNLOCK_BUTTON_XPATH), timeout)
        self._change_cell_status_on_modal(self._UNLOCK_STATUS, timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._AVAILABILITY_STATE_XATH), 'Unlocked', timeout)


